mapper.select:
SELECT RD.*
FROM shopwizard.tShpReturnDirect RD
INNER JOIN shopwizard.tCmpChnl Ch ON RD.ChnlCode = Ch.ChnlCode
INNER JOIN shopion.tOrdOrderProd OP ON OP.OrderNo = RD.OrderNo AND OP.OrderProdNo = RD.OrderProdNo
INNER JOIN shopion.tOrdOrder O ON OP.OrderNo = O.OrderNo


        AND ( RD.ReturnRqstDate IS NOT NULL AND RD.ReturnRqstDate != '' )
        AND ( RD.ReturnCmpletDate IS NULL OR RD.ReturnCmpletDate = '')

    AND Ch.SvcCode = #{pSvcCode}
    AND RD.OrderType = #{pOrderType}
    AND RD.ShopCode = #{pShopCode}
    AND RD.OrderNo = #{pOrderNo}
    AND RD.OrderProdNo = #{pOrderProdNo}
    AND RD.OrderChangeNo = #{pOrderChangeNo}
    AND RD.OrderName LIKE CONCAT('%',#{pOrderName},'%')
    AND RD.ChnlCode = #{pChnlCode}

        AND

            RD.ProdCode = #{pOrderSearchValue}
            RD.ProdName LIKE CONCAT('%',#{pOrderSearchValue},'%')
            RD.OrderNo = #{pOrderSearchValue}
            RD.OrderName LIKE CONCAT('%',#{pOrderSearchValue},'%')
            RD.RecverName LIKE CONCAT('%',#{pOrderSearchValue},'%')
            ( RD.OrderPhoneNo = #{pOrderSearchValue} OR RD.OrderMobileNo = #{pOrderSearchValue} OR RD.RecverPhoneNo = #{pOrderSearchValue} OR RD.RecverMobileNo = #{pOrderSearchValue} )
            OP.ChnlOrderNo LIKE CONCAT('%',#{pOrderSearchValue},'%')



        AND


                 ( O.PayCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND O.PayCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) 


                 ( OP.ShipCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND OP.ShipCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) 


                 ( O.RefundCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND O.RefundCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) 


                 ( O.OrderReciptDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND O.OrderReciptDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) 





    LIMIT ${pPageOffset}, ${pPageSize}

SELECT COUNT(*)
FROM shopwizard.tShpReturnDirect RD
INNER JOIN shopwizard.tCmpChnl Ch ON RD.ChnlCode = Ch.ChnlCode
INNER JOIN shopion.tOrdOrderProd OP ON OP.OrderNo = RD.OrderNo AND OP.OrderProdNo = RD.OrderProdNo
INNER JOIN shopion.tOrdOrder O ON OP.OrderNo = O.OrderNo


        AND ( RD.ReturnRqstDate IS NOT NULL AND RD.ReturnRqstDate != '' )
        AND ( RD.ReturnCmpletDate IS NULL OR RD.ReturnCmpletDate = '')

    AND Ch.SvcCode = #{pSvcCode}
    AND RD.OrderType = #{pOrderType}
    AND RD.ShopCode = #{pShopCode}
    AND RD.OrderNo = #{pOrderNo}
    AND RD.OrderProdNo = #{pOrderProdNo}
    AND RD.OrderChangeNo = #{pOrderChangeNo}
    AND RD.OrderName LIKE CONCAT('%',#{pOrderName},'%')
    AND RD.ChnlCode = #{pChnlCode}

        AND

            RD.ProdCode = #{pOrderSearchValue}
            RD.ProdName LIKE CONCAT('%',#{pOrderSearchValue},'%')
            RD.OrderNo = #{pOrderSearchValue}
            RD.OrderName LIKE CONCAT('%',#{pOrderSearchValue},'%')
            RD.RecverName LIKE CONCAT('%',#{pOrderSearchValue},'%')
            ( RD.OrderPhoneNo = #{pOrderSearchValue} OR RD.OrderMobileNo = #{pOrderSearchValue} OR RD.RecverPhoneNo = #{pOrderSearchValue} OR RD.RecverMobileNo = #{pOrderSearchValue} )
            OP.ChnlOrderNo LIKE CONCAT('%',#{pOrderSearchValue},'%')



        AND


                 ( O.PayCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND O.PayCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) 


                 ( OP.ShipCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND OP.ShipCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) 


                 ( O.RefundCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND O.RefundCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) 


                 ( O.OrderReciptDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND O.OrderReciptDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) )

SELECT *
FROM shopwizard.tShpReturnDirect
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
AND OrderChangeNo = #{orderChangeNo}

